import {METRE_CASES,metreCase,caseSyllables,scanPattern,decodeScansion,toggleStress} from './metre.js?v=2.5.1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const metreHTML=()=>'<section id="metre-analysis" class="metre-analysis" aria-label="Metrische Analyse"></section>';
export function mountMetre(root,{note,setNote,onTempo}){
 let current=metreCase(new URLSearchParams(location.hash.split('?')[1]||'').get('beispiel')||note('metric-selected','dach')),scan=decodeScansion(note('metric-'+current.id),current),showWords=false;
 const save=()=>setNote('metric-'+current.id,JSON.stringify(scan));
 function draw(){
  const flat=caseSyllables(current),original=Boolean(current.media);
  root.innerHTML=`<div class="metre-heading"><div><label class="field" for="metric-case">Textstelle</label><select id="metric-case">${['Originalstellen','Eigene Vergleichsverse'].map(group=>`<optgroup label="${group}">${METRE_CASES.filter(c=>c.group===group).map(c=>`<option value="${c.id}" ${current.id===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</optgroup>`).join('')}</select></div><label class="check-row"><input type="checkbox" id="metric-words" ${showWords?'checked':''}> Wortakzente einblenden</label></div><div class="metric-original">${original?`<div class="metric-video" id="metric-video"><button id="metric-load"><img src="https://i.ytimg.com/vi/${current.id==='dach'?'YPv1FTSmYNo':'EP5pdFjttQ4'}/hqdefault.jpg" alt="Originalvideo von Bodo Wartke" loading="lazy"><span>▶ Originalvideo laden</span></button></div>`:''}<div><p class="small">${esc(current.kind)}${original?' · Bodo Wartke':''}</p><p class="metric-reading">${esc(current.reading)}</p><p>${esc(current.question)}</p>${original?`<a href="${esc(current.source)}" target="_blank" rel="noopener noreferrer">Originalquelle</a>`:''}</div></div><div class="metric-score-head"><h2>Betonung und Pausen</h2><span class="small">∪ unbetont · / betont · | Pause</span></div><p class="small">Eine mögliche Sprechfassung. Klicke auf Silben, um die Betonung zu ändern, oder auf einen Zwischenraum für eine Pause.</p><div id="metric-score" class="metric-score"></div><div class="actions"><button id="metric-reset">Diese Lesart wiederherstellen</button><button id="metric-clear">Alle Betonungen entfernen</button></div><div id="metric-results" class="metric-results" role="status" aria-live="polite"></div><details class="metric-theory"><summary>Wortakzent, Metrum und Beat</summary><p>Der Wortakzent gehört zur Aussprache eines Wortes. Im Vers bilden Hebungen und Senkungen ein Muster; beim Sprechen können weitere Wörter hervorgehoben oder abgeschwächt werden.</p><p>Der Auftakt liegt vor der ersten Hebung. Die Kadenz bezeichnet den Versschluss: betont (männlich), mit einer unbetonten Endsilbe (weiblich) oder mit zwei unbetonten Endsilben (klingend).</p><p>Ein musikalischer Beat gibt ein zeitliches Raster vor. Mehrere Silben können auf einen Schlag fallen, eine betonte Silbe kann auch zwischen den Schlägen liegen. Für die Analyse des Raps gehören deshalb Text und Vortrag zusammen.</p><p>Unterstrichene Silben tragen den Wort-Hauptakzent. Die gestrichelte Linie markiert einen möglichen Nebenakzent. Bei einsilbigen Wörtern entscheidet der Satz- und Vortragszusammenhang über die Hervorhebung.</p><p><a href="https://grammis.ids-mannheim.de/systematische-grammatik/2344" target="_blank" rel="noopener noreferrer">IDS grammis · Wortakzent</a> · <a href="https://www.duden.de/rechtschreibung/endoplasmatisch" target="_blank" rel="noopener noreferrer">Duden · endoplasmatisch</a> · <a href="https://www.duden.de/rechtschreibung/Retikulum" target="_blank" rel="noopener noreferrer">Duden · Retikulum</a></p></details>`;
  root.querySelector('#metric-case').onchange=e=>{current=metreCase(e.target.value);scan=decodeScansion(note('metric-'+current.id),current);setNote('metric-selected',current.id);onTempo(current.tempo);draw();};
  root.querySelector('#metric-words').onchange=e=>{showWords=e.target.checked;score();};
  root.querySelector('#metric-reset').onclick=()=>{scan={pattern:current.pattern,pauses:[]};save();score();};
  root.querySelector('#metric-clear').onclick=()=>{scan={pattern:'0'.repeat(flat.length),pauses:[]};save();score();};
  if(original)root.querySelector('#metric-load').onclick=()=>{const id=current.id==='dach'?'YPv1FTSmYNo':'EP5pdFjttQ4';root.querySelector('#metric-video').innerHTML=`<iframe title="${esc(current.title)} · Bodo Wartke" src="https://www.youtube-nocookie.com/embed/${id}" allow="encrypted-media; fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;};
  score();
 }
 function score(){
  let index=0;root.querySelector('#metric-score').innerHTML=current.words.map(word=>`<span class="metric-word">${word.syllables.map((syllable,part)=>{const i=index++,stress=scan.pattern[i]==='1',accent=word.accents[part];return `<button class="metric-syllable ${stress?'stressed':''} ${showWords&&accent===1?'word-primary':showWords&&accent===2?'word-secondary':''}" data-metric-syllable="${i}" aria-pressed="${stress}" aria-label="${esc(syllable)} · ${stress?'betont':'unbetont'}"><span class="metric-mark" aria-hidden="true">${stress?'/':'∪'}</span><span>${esc(syllable)}</span></button>${i<scan.pattern.length-1?`<button class="metric-boundary ${scan.pauses.includes(i+1)?'has-pause':''}" data-metric-pause="${i+1}" aria-pressed="${scan.pauses.includes(i+1)}" aria-label="Pause nach ${esc(syllable)}">${scan.pauses.includes(i+1)?'|':'·'}</button>`:''}`;}).join('')}</span>`).join('');
  root.querySelectorAll('[data-metric-syllable]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.metricSyllable);scan.pattern=toggleStress(scan.pattern,i);save();score();root.querySelector(`[data-metric-syllable="${i}"]`).focus({preventScroll:true});});
  root.querySelectorAll('[data-metric-pause]').forEach(b=>b.onclick=()=>{const at=Number(b.dataset.metricPause);scan.pauses=scan.pauses.includes(at)?scan.pauses.filter(i=>i!==at):[...scan.pauses,at].sort((a,b)=>a-b);save();score();root.querySelector(`[data-metric-pause="${at}"]`).focus({preventScroll:true});});
  const result=scanPattern(scan.pattern),label=result.meter?`${result.meter} · ${result.stresses} Hebungen`:'Wechselnde Senkungsfüllung';
  root.querySelector('#metric-results').innerHTML=`<dl><div><dt>Silben</dt><dd>${result.syllables}</dd></div><div><dt>Hebungen</dt><dd>${result.stresses}</dd></div><div><dt>Auftakt</dt><dd>${result.lead===null?'–':result.lead+' '+(result.lead===1?'Silbe':'Silben')}</dd></div><div><dt>Kadenz</dt><dd>${result.cadence}</dd></div></dl><p><strong>Betonungsfolge:</strong> ${esc(result.stresses<2?'Für den Vergleich fehlen weitere Hebungen.':label)}</p>${result.gaps.length?`<p><strong>Senkungen zwischen den Hebungen:</strong> ${result.gaps.join(' · ')}</p>`:''}<p class="small">${current.id==='er'?'Hier wird der Fachbegriff untersucht. Für das Versmass zählt die vollständige Zeile.':result.meter?'Die markierte Folge passt zum angegebenen Versmass.':'Vergleiche die Abstände der Hebungen und die Verteilung im Vortrag.'}</p>`;
 }
 onTempo(current.tempo);draw();
}
